const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' }));
const dayOfWeek = now.getDay(); // 0=Sun ... 1=Mon
const dayOfMonth = now.getDate();
const month = now.getMonth() + 1; // 1-12
const isMonday = dayOfWeek === 1;
const isFirstOfMonth = dayOfMonth === 1;
const isQuarterStart = isFirstOfMonth && [1,4,7,10].includes(month);

return [{
  json: {
    runDate: now.toISOString(),
    isMonday,
    isFirstOfMonth,
    isQuarterStart
  }
}];

// Each source's raw payload shape differs; this maps every known shape
// into: course_name, search_volume, popularity_score, hiring_demand,
// mentions, discussion_count, growth_pct, raw_payload
const src = $('Loop Sources (SplitInBatches)').item.json;
const body = $input.first().json;
const out = [];

function push(courseName, fields) {
  out.push({
    json: {
      course_name: courseName,
      normalized_name: String(courseName).trim().toLowerCase(),
      source_type: src.source_type,
      search_volume: fields.search_volume || 0,
      popularity_score: fields.popularity_score || 0,
      hiring_demand: fields.hiring_demand || 0,
      mentions: fields.mentions || 0,
      discussion_count: fields.discussion_count || 0,
      growth_pct: fields.growth_pct || 0,
      raw_payload: fields.raw || {}
    }
  });
}

try {
  switch (src.source_type) {
    case 'google_trends': {
      const items = body.trending_searches || body.related_topics || [];
      items.forEach(i => push(i.query || i.title, { search_volume: i.search_volume || i.value || 0, growth_pct: i.increase_percentage || 0, raw: i }));
      break;
    }
    case 'google_news': {
      (body.news_results || []).forEach(i => push(i.title, { mentions: 1, raw: i }));
      break;
    }
    case 'reddit': {
      (body.data?.children || []).forEach(c => push(c.data.title, { discussion_count: c.data.num_comments || 0, popularity_score: c.data.score || 0, raw: c.data }));
      break;
    }
    case 'youtube': {
      (body.items || []).forEach(i => push(i.snippet?.title, { mentions: 1, raw: i }));
      break;
    }
    case 'linkedin_jobs': {
      (body.elements || []).forEach(i => push(i.title, { hiring_demand: 1, raw: i }));
      break;
    }
    default: {
      // scrape_proxy sources return { items: [{ name, count, ... }] } from the proxy's parser
      (body.items || []).forEach(i => push(i.name || i.course || i.title, {
        search_volume: i.search_volume || 0,
        popularity_score: i.popularity || 0,
        hiring_demand: i.hiring_demand || i.job_count || 0,
        mentions: i.mentions || 0,
        discussion_count: i.discussions || 0,
        growth_pct: i.growth_pct || 0,
        raw: i
      }));
    }
  }
} catch (e) {
  out.push({ json: { error: true, source_type: src.source_type, message: e.message, raw_payload: body } });
}

return out.length ? out : [{ json: { source_type: src.source_type, empty: true } }];

// Trend Score = normalized weighted sum of the 5 signal groups.
// Weights are configurable via env vars so the Learning Engine can tune them over time.
const W_SEARCH   = parseFloat($env.TREND_WEIGHT_SEARCH   || '0.25');
const W_HIRING   = parseFloat($env.TREND_WEIGHT_HIRING   || '0.25');
const W_DISCUSS  = parseFloat($env.TREND_WEIGHT_DISCUSS  || '0.2');
const W_NEWS     = parseFloat($env.TREND_WEIGHT_NEWS     || '0.15');
const W_SOCIAL   = parseFloat($env.TREND_WEIGHT_SOCIAL   || '0.15');

const rows = $input.all().map(i => i.json);

function minMax(arr, key) {
  const vals = arr.map(r => Number(r[key]) || 0);
  const min = Math.min(...vals), max = Math.max(...vals);
  return v => (max === min ? 0 : ((Number(v) || 0) - min) / (max - min));
}
const normSearch  = minMax(rows, 'total_search_volume');
const normHiring   = minMax(rows, 'total_hiring_demand');
const normDiscuss  = minMax(rows, 'total_discussion');
const normNews     = minMax(rows, 'total_mentions');
const normSocial   = minMax(rows, 'total_social_engagement');

const scored = rows.map(r => {
  const score = 100 * (
    W_SEARCH  * normSearch(r.total_search_volume) +
    W_HIRING  * normHiring(r.total_hiring_demand) +
    W_DISCUSS * normDiscuss(r.total_discussion) +
    W_NEWS    * normNews(r.total_mentions) +
    W_SOCIAL  * normSocial(r.total_social_engagement)
  );
  return { ...r, trend_score: Math.round(score * 100) / 100 };
});

scored.sort((a, b) => b.trend_score - a.trend_score);
const top10 = scored.slice(0, 10).map((r, idx) => ({ ...r, rank_position: idx + 1 }));

return top10.map(r => ({ json: r }));

