const course = $json.course_name;

const groups = [
  {
    group: 'basic_info',
    fields: ['description','eligibility','duration','entrance_exams','emerging_trends'],
    prompt: `Research the graduation course "${course}" in India. Return strict JSON with keys: description, eligibility, duration, entrance_exams (array), emerging_trends. Ground every claim in a real, citable source and include a matching "sources" object mapping each key to an array of source URLs.`
  },
  {
    group: 'colleges',
    fields: ['government_colleges','private_colleges'],
    prompt: `List top government and private colleges in India offering "${course}". Return strict JSON: { government_colleges: [{name, city, fees_annual}], private_colleges: [{name, city, fees_annual}], sources: [...] }.`
  },
  {
    group: 'salary_career',
    fields: ['average_salary','highest_salary','placement_percent','recruiters','career_path'],
    prompt: `For graduates of "${course}" in India, return strict JSON: { average_salary, highest_salary, placement_percent, recruiters (array), career_path, sources }. Use INR annual figures.`
  },
  {
    group: 'opportunities',
    fields: ['industry_demand','future_scope','abroad_opportunities','scholarships'],
    prompt: `Describe industry demand, future scope, abroad opportunities, and scholarships available for "${course}" graduates from India. Return strict JSON with those 4 keys plus sources.`
  },
  {
    group: 'community',
    fields: ['faq','student_pain_points','student_myths','latest_news'],
    prompt: `Compile 5 FAQs, 3 common student pain points, 3 myths, and 3 recent (last 6 months) news items about "${course}" in India. Return strict JSON: { faq: [{q,a}], student_pain_points: [], student_myths: [], latest_news: [{headline, summary, url, published_at}], sources }.`
  }
];

return groups.map(g => ({ json: { course_name: course, ...g } }));

const group = $('Loop Field Groups').item.json;
let modelUsed = 'gemini-2.5-pro';
let raw;

try {
  if ($json.candidates) {
    modelUsed = 'gemini-2.5-pro';
    raw = JSON.parse($json.candidates[0].content.parts[0].text);
  } else if ($json.output) {
    modelUsed = 'gpt-5.5';
    const textPart = $json.output.find(o => o.type === 'message');
    raw = JSON.parse(textPart.content[0].text);
  } else {
    throw new Error('Unrecognized model response shape');
  }
} catch (e) {
  return [{ json: { parseError: true, message: e.message, group: group.group, course_name: group.course_name } }];
}

const sources = raw.sources || {};
const rows = group.fields.map(fieldKey => ({
  json: {
    course_name: group.course_name,
    field_key: fieldKey,
    field_value: typeof raw[fieldKey] === 'string' ? raw[fieldKey] : JSON.stringify(raw[fieldKey] ?? null),
    model_used: modelUsed,
    source_urls: Array.isArray(sources[fieldKey]) ? sources[fieldKey] : (Array.isArray(sources) ? sources : []),
    raw_payload: raw
  }
}));

return rows;

