const field = $('Loop Fields').item.json;
const claimed = parseFloat(field.field_value) || 0;
const inputs = $input.all().map(i => i.json);

// Extract a comparable numeric value from each source's response shape.
const extracted = inputs.map(r => {
  const v = r.medianSalary ?? r.average_salary ?? r.value ?? r.salary ?? null;
  return v != null ? parseFloat(v) : null;
}).filter(v => v != null && !isNaN(v));

let agreementPct = 0;
let sourceCount = extracted.length;

if (sourceCount > 0 && claimed > 0) {
  const withinTolerance = extracted.filter(v => Math.abs(v - claimed) / claimed <= 0.15).length;
  agreementPct = Math.round((withinTolerance / sourceCount) * 10000) / 100;
} else if (sourceCount === 0) {
  agreementPct = 0;
}

const confidence = Math.round((agreementPct / 100) * (Math.min(sourceCount, 4) / 4) * 100) / 100;
const reviewStatus = agreementPct >= 80 ? 'verified' : 'flagged';

return [{
  json: {
    course_name: field.course_name,
    fact_key: field.field_key,
    fact_value: field.field_value,
    source_count: sourceCount,
    agreement_pct: agreementPct,
    confidence_score: confidence,
    review_status: reviewStatus,
    source_urls: field.source_urls || []
  }
}];

// Non cross-checkable fields (description, eligibility, FAQs, news, etc.)
// are scored on source_count and model agreement between Gemini/GPT if both ran,
// never treated as auto-verified.
const field = $json;
const sourceCount = Array.isArray(field.source_urls) ? field.source_urls.length : 0;
const confidence = Math.min(1, sourceCount / 3) * 0.85; // capped below numeric-verified facts
const reviewStatus = sourceCount >= 2 ? 'verified' : 'flagged';

return [{
  json: {
    course_name: field.course_name,
    fact_key: field.field_key,
    fact_value: field.field_value,
    source_count: sourceCount,
    agreement_pct: sourceCount >= 2 ? 100 : 0,
    confidence_score: Math.round(confidence * 100) / 100,
    review_status: reviewStatus,
    source_urls: field.source_urls || []
  }
}];

