const facts = $input.all().map(i => i.json);
if (!facts.length) return [{ json: { skip: true } }];

const byKey = {};
facts.forEach(f => { byKey[f.fact_key] = f; });

function val(key) { return byKey[key] ? byKey[key].fact_value : null; }
function tryJson(key) { try { return JSON.parse(val(key)); } catch (e) { return null; } }

const confidences = facts.map(f => Number(f.confidence_score) || 0);
const avgConfidence = confidences.length ? Math.round((confidences.reduce((a,b)=>a+b,0)/confidences.length)*100)/100 : 0;

return [{
  json: {
    course_id: facts[0].course_id,
    course_name: facts[0].course_name,
    description: val('description'),
    eligibility: val('eligibility'),
    duration: val('duration'),
    entrance_exams: tryJson('entrance_exams') || [],
    emerging_trends: val('emerging_trends'),
    future_scope: val('future_scope'),
    career_path: val('career_path'),
    abroad_opportunities: val('abroad_opportunities'),
    scholarships: val('scholarships'),
    government_colleges: tryJson('government_colleges') || [],
    private_colleges: tryJson('private_colleges') || [],
    average_salary: val('average_salary'),
    highest_salary: val('highest_salary'),
    placement_percent: val('placement_percent'),
    recruiters: tryJson('recruiters') || [],
    industry_demand: val('industry_demand'),
    faq: tryJson('faq') || [],
    latest_news: tryJson('latest_news') || [],
    student_pain_points: tryJson('student_pain_points') || [],
    student_myths: tryJson('student_myths') || [],
    confidence_score: avgConfidence,
    review_status: avgConfidence >= 0.8 ? 'verified' : 'flagged'
  }
}];

const rec = $('Build Denormalized Course Record').item.json;
const rows = [];
(rec.government_colleges || []).forEach(c => rows.push({ ...c, type: 'government' }));
(rec.private_colleges || []).forEach(c => rows.push({ ...c, type: 'private' }));
return rows.map(r => ({ json: { course_id: rec.course_id, name: r.name, type: r.type, city: r.city || null, fees_annual: r.fees_annual || null } }));

const rec = $('Build Denormalized Course Record').item.json;
const rows = [];
(rec.faq || []).forEach(f => rows.push({ course_id: rec.course_id, question: f.q, answer: f.a, category: 'faq' }));
(rec.student_pain_points || []).forEach(p => rows.push({ course_id: rec.course_id, question: 'Common pain point', answer: p, category: 'pain_point' }));
(rec.student_myths || []).forEach(m => rows.push({ course_id: rec.course_id, question: 'Common myth', answer: m, category: 'myth' }));
return rows.map(r => ({ json: r }));

const platforms = [
  'instagram_reel','youtube_shorts','linkedin_post','facebook_post',
  'pinterest','telegram','whatsapp','blog','newsletter'
];
const kb = $json;
return platforms.map(p => ({ json: { platform: p, kb } }));

const loopItem = $('Loop Platforms').item.json;
const kb = loopItem.kb;
const platform = loopItem.platform;
const template = $input.first().json;

const baseFacts = `Course: ${kb.name}
Description: ${kb.description}
Average Salary: ${kb.salaries?.[0]?.average_salary || 'N/A'}
Top Colleges: ${(kb.colleges||[]).slice(0,3).map(c=>c.name).join(', ')}
Career Path: ${kb.career_path}
Future Scope: ${kb.future_scope}
Latest News: ${(kb.news||[]).map(n=>n.headline).join(' | ')}`;

const REEL_FORMAT = `Output STRICT JSON: { hook (0-3s), problem (3-10s), opportunity (10-20s), evidence (20-27s), cta (27-30s) }. Combined word count across all 5 fields MUST be <= 90 words. Base every claim only on the facts provided below — do not invent statistics.`;

const defaultPrompts = {
  instagram_reel: `${REEL_FORMAT}

FACTS:
${baseFacts}`,
  youtube_shorts: `Write a 45-second YouTube Shorts script (hook/body/cta) for the course below, <=140 words total, punchy, vertical-video pacing.

FACTS:
${baseFacts}`,
  linkedin_post: `Write a professional LinkedIn post (120-180 words) about this course's career prospects, ending with a question to drive comments.

FACTS:
${baseFacts}`,
  facebook_post: `Write a friendly, parent-and-student-facing Facebook post (80-120 words) about this course.

FACTS:
${baseFacts}`,
  pinterest: `Write a Pinterest pin title (<=100 chars) and description (<=500 chars) for this course, keyword-rich for search.

FACTS:
${baseFacts}`,
  telegram: `Write a concise Telegram channel post (<=100 words) with 3 bullet facts and a CTA to view the full guide.

FACTS:
${baseFacts}`,
  whatsapp: `Write a WhatsApp broadcast message (<=60 words), conversational, one clear CTA link placeholder {{link}}.

FACTS:
${baseFacts}`,
  blog: `Write a structured 600-800 word blog article (H2 sections: Overview, Eligibility, Fees & Colleges, Salary & Placements, Future Scope, FAQs) about this course, using only the facts provided plus the FAQ list.

FACTS:
${baseFacts}
FAQ:
${JSON.stringify(kb.faq||[])}`,
  newsletter: `Write a newsletter section (200-250 words) introducing this trending course to subscribers, with a 'Why it matters now' angle grounded in the latest news.

FACTS:
${baseFacts}`
};

const prompt = (template && template.template_body) ? template.template_body.replace('{{FACTS}}', baseFacts).replace('{{FAQ}}', JSON.stringify(kb.faq||[])) : defaultPrompts[platform];

return [{ json: { platform, course_id: kb.id, course_name: kb.name, prompt, template_id: template?.id || null } }];

const ctx = $('Build Final Prompt').item.json;
const resp = $json;
let text;
try {
  const msg = resp.output.find(o => o.type === 'message');
  text = msg.content[0].text;
} catch (e) {
  return [{ json: { error: true, message: 'Could not parse GPT-5.5 output', ctx } }];
}

let parsed;
try { parsed = JSON.parse(text); } catch (e) { parsed = { body: text }; }

let scriptJson = null;
let body = '';
let wordCount = 0;

if (ctx.platform === 'instagram_reel') {
  scriptJson = parsed;
  body = ['hook','problem','opportunity','evidence','cta'].map(k => parsed[k]).join(' ');
  wordCount = body.trim().split(/\s+/).length;
} else if (ctx.platform === 'pinterest') {
  body = parsed.description || parsed.body || text;
} else {
  body = parsed.body || parsed.text || text;
}

return [{
  json: {
    course_id: ctx.course_id,
    platform: ctx.platform,
    title: parsed.title || parsed.hook || null,
    body,
    hashtags: parsed.hashtags || [],
    metadata: JSON.stringify(parsed.metadata || {}),
    script_json: ctx.platform === 'instagram_reel' ? JSON.stringify(scriptJson) : null,
    reel_word_count: wordCount,
    reel_over_limit: ctx.platform === 'instagram_reel' && wordCount > 90
  }
}];

const item = $json;
const script = JSON.parse(item.script_json);
const order = ['hook','problem','opportunity','evidence','cta'];
let words = [];
order.forEach(k => { words = words.concat((script[k]||'').split(/\s+/)); });
const trimmed = words.slice(0, 90).join(' ');
return [{ ...$input.first(), json: { ...item, body: trimmed, reel_over_limit: false } }];

const variant = $('Pick Next Wardrobe/Background Variant').item.json;
const content = $('Fetch content_item + course').item.json;
let scenes;
try {
  scenes = JSON.parse($json.candidates[0].content.parts[0].text);
} catch (e) {
  return [{ json: { error: true, message: 'Scene breakdown parse failure: ' + e.message } }];
}

return [{
  json: {
    content_item_id: content.id,
    course_name: content.course_name,
    avatar_id: $env.HEYGEN_AVATAR_ID,
    wardrobe_variant: variant.wardrobe_variant,
    background_variant: variant.background_variant,
    heygen_look_id: variant.heygen_look_id,
    scene_breakdown: scenes
  }
}];

const p = $('Parse Scene Breakdown').item.json;
const scenes = p.scene_breakdown.scenes || [];

// Every scene reuses the SAME avatar_id (identity) but applies the
// look/outfit + background chosen for THIS render, so the presenter
// stays recognizable while wardrobe + studio rotate render-to-render.
const videoInputs = scenes.map(s => ({
  character: {
    type: 'avatar',
    avatar_id: p.avatar_id,
    avatar_style: 'normal',
    look_id: p.heygen_look_id || undefined,
    talking_style: s.gesture,
    expression: s.facial_expression
  },
  voice: {
    type: 'text',
    input_text: s.narration,
    voice_id: $env.HEYGEN_VOICE_ID,
    speed: 1.0
  },
  background: {
    type: 'image',
    image_asset_id: p.background_variant // pre-uploaded HeyGen asset id for this studio background
  }
}));

const payload = {
  video_inputs: videoInputs,
  dimension: { width: 1080, height: 1920 },
  caption: true,
  test: $env.HEYGEN_TEST_MODE === 'true'
};

return [{ json: { heygen_payload: payload, content_item_id: p.content_item_id } }];

const item = $('Loop Content Items').item.json;
let meta = {};
try {
  const msg = $json.output.find(o => o.type === 'message');
  meta = JSON.parse(msg.content[0].text);
} catch (e) { meta = {}; }
return [{ json: { ...item, publish_metadata: meta } }];

const target = $('Loop Publish Targets').item.json;
const body = $json;
const platform = target.platform;

function fromMeta() {
  const d = {};
  (body.data || []).forEach(m => { d[m.name] = m.values?.[0]?.value || 0; });
  return { views: d.impressions || 0, reach: d.reach || 0, likes: d.likes || 0, comments: d.comments || 0, shares: d.shares || 0, saves: d.saved || 0, watch_time_seconds: 0 };
}
function fromYoutube() {
  const row = body.rows?.[0] || [];
  return { views: row[0]||0, watch_time_seconds: (row[1]||0)*60, retention_pct: row[2]||0, likes: row[3]||0, comments: row[4]||0, shares: row[5]||0, new_subscribers: row[6]||0 };
}
function fromLinkedin() {
  const el = body.elements?.[0]?.totalShareStatistics || {};
  return { views: el.impressionCount||0, likes: el.likeCount||0, comments: el.commentCount||0, shares: el.shareCount||0, ctr_pct: el.clickCount && el.impressionCount ? (el.clickCount/el.impressionCount*100) : 0 };
}
function fromPinterest() {
  const d = body.all?.summary_metrics || {};
  return { views: d.IMPRESSION||0, saves: d.SAVE||0, ctr_pct: d.OUTBOUND_CLICK_RATE||0 };
}
function fromX() {
  const m = body.data?.public_metrics || {};
  return { views: m.impression_count||0, likes: m.like_count||0, comments: m.reply_count||0, shares: m.retweet_count||0 };
}

let metrics = {};
if (['instagram_reel','facebook_post'].includes(platform)) metrics = fromMeta();
else if (platform === 'youtube_shorts') metrics = fromYoutube();
else if (platform === 'linkedin_post') metrics = fromLinkedin();
else if (platform === 'pinterest') metrics = fromPinterest();
else if (platform === 'x') metrics = fromX();

return [{ json: { publish_target_id: target.id, raw_payload: body, ...metrics } }];

return [
  { json: { insight_type: 'best_hook', query: `SELECT ci.script_json->>'hook' AS hook, AVG(a.completion_rate_pct) AS avg_completion, AVG(a.views) AS avg_views FROM content_items ci JOIN video_assets va ON va.content_item_id = ci.id JOIN publish_targets pt ON pt.video_asset_id = va.id JOIN analytics a ON a.publish_target_id = pt.id WHERE ci.platform='instagram_reel' AND ci.script_json IS NOT NULL GROUP BY hook ORDER BY avg_completion DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_cta', query: `SELECT ci.script_json->>'cta' AS cta, AVG(a.ctr_pct) AS avg_ctr FROM content_items ci JOIN video_assets va ON va.content_item_id = ci.id JOIN publish_targets pt ON pt.video_asset_id = va.id JOIN analytics a ON a.publish_target_id = pt.id WHERE ci.script_json IS NOT NULL GROUP BY cta ORDER BY avg_ctr DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_duration', query: `SELECT va.duration_seconds, AVG(a.retention_pct) AS avg_retention FROM video_assets va JOIN publish_targets pt ON pt.video_asset_id = va.id JOIN analytics a ON a.publish_target_id = pt.id GROUP BY va.duration_seconds ORDER BY avg_retention DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_course_category', query: `SELECT c.category, AVG(a.views) AS avg_views FROM courses c JOIN content_items ci ON ci.course_id = c.id JOIN publish_targets pt ON pt.content_item_id = ci.id JOIN analytics a ON a.publish_target_id = pt.id GROUP BY c.category ORDER BY avg_views DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_posting_time', query: `SELECT EXTRACT(HOUR FROM pt.published_at) AS post_hour, AVG(a.views) AS avg_views FROM publish_targets pt JOIN analytics a ON a.publish_target_id = pt.id GROUP BY post_hour ORDER BY avg_views DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_avatar_variant', query: `SELECT va.wardrobe_variant, va.background_variant, AVG(a.completion_rate_pct) AS avg_completion FROM video_assets va JOIN publish_targets pt ON pt.video_asset_id = va.id JOIN analytics a ON a.publish_target_id = pt.id GROUP BY va.wardrobe_variant, va.background_variant ORDER BY avg_completion DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_broll_style', query: `SELECT jsonb_array_elements(va.scene_breakdown->'scenes')->>'broll_prompt' AS broll_prompt, AVG(a.retention_pct) AS avg_retention FROM video_assets va JOIN publish_targets pt ON pt.video_asset_id = va.id JOIN analytics a ON a.publish_target_id = pt.id GROUP BY broll_prompt ORDER BY avg_retention DESC NULLS LAST LIMIT 5;` } },
  { json: { insight_type: 'best_thumbnail', query: `SELECT ci.metadata->>'thumbnail_prompt' AS thumbnail_prompt, AVG(a.ctr_pct) AS avg_ctr FROM content_items ci JOIN publish_targets pt ON pt.content_item_id = ci.id JOIN analytics a ON a.publish_target_id = pt.id WHERE ci.metadata->>'thumbnail_prompt' IS NOT NULL GROUP BY thumbnail_prompt ORDER BY avg_ctr DESC NULLS LAST LIMIT 5;` } }
];

const dim = $('Loop Dimensions').item.json;
const rows = $('Run Dimension Query (Postgres)').all().map(i => i.json);
let parsed;
try { parsed = JSON.parse($json.candidates[0].content.parts[0].text); }
catch (e) { parsed = { finding: 'insufficient data', confidence: 0, recommended_change: null }; }

return [{
  json: {
    insight_type: dim.insight_type,
    finding: parsed.finding,
    confidence: parsed.confidence,
    recommended_change: parsed.recommended_change,
    supporting_data: rows
  }
}];

const insight = $('Parse Insight').item.json;
const map = {
  best_hook: 'instagram_reel',
  best_cta: 'instagram_reel',
  best_duration: 'scene_breakdown',
  best_avatar_variant: 'scene_breakdown',
  best_broll_style: 'scene_breakdown',
  best_thumbnail: 'youtube_shorts',
  best_posting_time: null,
  best_course_category: null
};
const templateKey = map[insight.insight_type];
if (!templateKey) return [{ json: { skip: true } }];
return [{ json: { template_key: templateKey, recommended_change: insight.recommended_change, insight_id: $json.id } }];

parameters.jsonBody:
={{ JSON.stringify({ model: 'gpt-5.5', input: `Current prompt template (${$json.template_key} v${$json.version}):
${$json.template_body}

Apply this recommended change while preserving the required output JSON schema and hard word/time limits: ${$('Map Insight to Template Key').item.json.recommended_change}. Return only the revised prompt template text.` }) }}

parameters.query:
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['courses','course_facts','colleges','careers','salaries','skills','news','faq','content_items','video_assets','publish_targets','analytics','prompt_templates','learning_insights'] LOOP
    EXECUTE format('DELETE FROM %I WHERE deleted_at IS NOT NULL AND deleted_at < now() - interval ''180 days''', t);
  END LOOP;
END $$;
